function demotedRow(name,mode,who){var icon,txt;if(mode==='stop'){icon='ti-eye-off';txt='No longer tracking';}else if(mode==='snoozew'){icon='ti-zzz';txt='Snoozed, back in about a week';}else{icon='ti-zzz';txt='Snoozed, back in about a day';}return '<div class="card demoted"><div style="display:flex;align-items:center;gap:9px;">'+SIC(icon,18,'color:var(--text-muted);')+'<div style="flex:1;min-width:0;"><p style="font-size:14px;font-weight:500;margin:0;">'+name+'</p><p style="font-size:11.5px;color:var(--text-muted);margin:1px 0 0;">'+txt+'</p></div><button class="lbtn" data-a="unsnooze-'+who+'">Undo</button></div></div>';}
function isOn(name){return S.onOrder.some(function(o){return o.n===name;});}
function toast(m){toastEl.textContent=m;toastEl.classList.add('show');clearTimeout(tt);tt=setTimeout(function(){toastEl.classList.remove('show');},3000);}
function tItem(){return cat[0];}
function trend(a){var f=a[0],l=a[a.length-1];return l>f*1.12?'climbing':(l<f*0.9?'slowing':'steady');}
function chart(it){var a=it.h.concat([it.fc]),w=290,h=54,pad=6;var mn=Math.min.apply(null,a),mx=Math.max.apply(null,a),r=(mx-mn)||1;function X(i){return (i/(a.length-1))*w;}function Y(v){return h-pad-((v-mn)/r)*(h-2*pad);}var hp=it.h.map(function(v,i){return X(i).toFixed(1)+','+Y(v).toFixed(1);}).join(' ');var lx=X(it.h.length-1),ly=Y(it.h[it.h.length-1]),fx=X(a.length-1),fy=Y(it.fc);return '<svg width="100%" viewBox="0 0 '+w+' '+h+'"><polyline points="'+hp+'" fill="none" stroke="'+it.tc+'" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"/><line x1="'+lx.toFixed(1)+'" y1="'+ly.toFixed(1)+'" x2="'+fx.toFixed(1)+'" y2="'+fy.toFixed(1)+'" stroke="'+it.tc+'" stroke-width="2" stroke-dasharray="3 3" opacity=".7"/><circle cx="'+fx.toFixed(1)+'" cy="'+fy.toFixed(1)+'" r="3.5" fill="'+it.tc+'"/></svg>';}

var INFO={
  review:{t:'Review the ones running low',b:'In the full product, this opens a focused list of just the 3 items running low, each with its own trend and a one-tap reorder. A filtered view, not the whole budget planner.'},
  dead:{t:'Free up trapped cash',b:'This opens your 3 slow movers with the cash each one is tying up, and lets you free it with a markdown. The other half of the money story: not just what to buy, but what to stop holding.'},
  ask:{t:'Ask Stockpilot',b:'A conversational way to ask anything, like what to restock this week, and drop into the planner from your own words. The proactive feed stays the default, conversation is the depth on demand.'},
  reviewdone:{t:'The items running low',b:'In the full product, this shows the items that were running low and are now on order, so you can confirm exactly what got reordered.'},
  reagain:{t:'Reorder from a past order',b:'In the full product, this starts a reorder pre-filled with the same items and quantities as this past order, which you can adjust before sending.'}
};
