  h+='<div style="padding:14px 16px 0;"><p style="font-size:12px;color:var(--text-muted);margin:0 0 2px;">Suggested mix, tap a row for why</p><div id="pl-mix"></div><div style="display:flex;align-items:center;justify-content:space-between;padding:12px 0 4px;"><span style="font-size:13px;color:var(--text-secondary);">Allocated</span><span id="pl-total" style="font-size:16px;font-weight:600;"></span></div></div>';
